python3 - <<'PY'
import json,re,subprocess,pathlib,sys
db=next(x for x in subprocess.check_output(["docker","ps","--format","{{.Names}}"],text=True).splitlines() if re.search(r"postgres|database|db-[0-9]",x,re.I))
sql="""SELECT message_id FROM topic_dm_entry_pins WHERE chat_id=-1002373696859
AND message_thread_id=1605 AND state='published' AND pinned=TRUE AND token_hash IS NOT NULL"""
p=subprocess.run(["docker","exec",db,"sh","-c",'psql -qAt -U "$POSTGRES_USER" -d "$POSTGRES_DB" -c "$1"',"sh",sql],capture_output=True,text=True)
ids=p.stdout.splitlines()
if p.returncode or len(ids)!=1 or not ids[0].isdigit():sys.exit(90)
mid=int(ids[0])
line=next(x for x in pathlib.Path('/tmp/video-topic-userbot-audit.out').read_text().splitlines() if x.startswith('USERBOT_TOPIC_AUDIT='))
row=json.loads(line.split('=',1)[1])['rows'][0]
if mid not in row.get('history_message_ids',[]) or row.get('pin_state')=='PRESENT':sys.exit(91)
js="""import fs from 'node:fs';
const token=process.env.BOT_TOKEN_FILE?fs.readFileSync(process.env.BOT_TOKEN_FILE,'utf8').trim():process.env.BOT_TOKEN;
if(!/^[0-9]{7,15}:[A-Za-z0-9_-]{30,100}$/.test(token??''))process.exit(31);
const id=Number(process.env.PIN_MSG_ID);
if(!Number.isSafeInteger(id)||id<=0)process.exit(32);
const res=await fetch('https://api.telegram.org/bot'+token+'/pinChatMessage',{
 method:'POST',headers:{'content-type':'application/json'},
 body:JSON.stringify({chat_id:-1002373696859,message_id:id,disable_notification:true})
});
const payload=await res.json();
if(!payload.ok){console.error('TELEGRAM_VIDEO_PIN_ERROR_CODE='+String(payload.error_code??'UNKNOWN'));process.exit(33)}
console.log('TELEGRAM_VIDEO_REPIN=PASS');"""
r=subprocess.run(["docker","exec","-e","PIN_MSG_ID="+str(mid),"deploy-gaybbs-1","node","--import","/app/preload/telegram-ipv4-preload.mjs","--input-type=module","-e",js],capture_output=True,text=True,timeout=50)
if r.returncode:sys.exit(92)
if "TELEGRAM_VIDEO_REPIN=PASS" not in r.stdout:sys.exit(93)
print("TELEGRAM_VIDEO_REPIN=PASS")
